js='''(function(){let theme=localStorage.getItem('theme')||'dark';document.documentElement.dataset.theme=theme;let b=document.getElementById('themeToggle');if(b)b.addEventListener('click',()=>{theme=theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;localStorage.setItem('theme',theme)});let menu=document.getElementById('mobileMenu'),bar=document.getElementById('sidebar'),overlay=document.getElementById('overlay');function toggle(){bar.classList.toggle('open');overlay.classList.toggle('open')}if(menu)menu.addEventListener('click',toggle);if(overlay)overlay.addEventListener('click',toggle);let input=document.getElementById('searchInput');if(input){let cards=[...document.querySelectorAll('[data-search]')],empty=document.getElementById('noResults');function filter(){let q=input.value.toLowerCase().trim(),count=0;for(let card of cards){let show=card.dataset.search.toLowerCase().includes(q);card.style.display=show?'':'none';if(show)count++}empty.hidden=count!==0}input.addEventListener('input',filter);filter();}})();'''
