icons={'home':'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>','pen':'<path d="M12 20h9M16 4l4 4-12 12-5 1 1-5z"/>','spark':'<path d="m12 3 1.7 5.3L19 10l-5.3 1.7L12 17l-1.7-5.3L5 10l5.3-1.7z M19 17l.8 2.2L22 20l-2.2.8L19 23l-.8-2.2L16 20l2.2-.8z"/>','tags':'<path d="M20 12l-8 8-9-9V4h7z"/><circle cx="7.5" cy="8" r="1"/>','folder':'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11H3z"/>','user':'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-5 16-5 16 0"/>','search':'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>','moon':'<path d="M20 15a8 8 0 0 1-11-11 8 8 0 1 0 11 11"/>','menu':'<path d="M4 6h16M4 12h16M4 18h16"/>','mail':'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>','external':'<path d="M13 4h7v7M20 4l-9 9M20 14v6H4V4h6"/>','terminal':'<path d="m4 6 6 6-6 6M12 18h8"/>'}
def ico(name):return '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+icons[name]+'</svg>'
def esc(s):return html.escape(s,quote=True)
def meta(p):return f'<div class="meta"><span>◷ {p["date"]}</span><span>▤ {esc(p["category"])}</span><span>◷ {p["read"]}</span></div>'
def pills(p):return '<div class="pills">'+''.join(f'<a class="pill" href="tags.html#{esc(t.lower().replace(" ","-"))}">#{esc(t)}</a>' for t in p['tags'])+'</div>'
def postcard(p):return f'<article class="post" data-search="{esc(" ".join([p["title"],p["summary"],p["category"]]+p["tags"]))}">{meta(p)}<h2><a href="{p["slug"]}.html">{esc(p["title"])}</a>{"<span class=mark>Sample</span>" if p.get("sample") else ""}</h2><p>{esc(p["summary"])}</p>{pills(p)}</article>'
def layout(page,title,body,desc='Cybersecurity writeups and personal notes'):
 nav=[('index.html','Home','home'),('writeups.html','Writeups','pen'),('thoughts.html','Thoughts','spark'),('categories.html','Categories','folder'),('tags.html','Tags','tags'),('about.html','About','user')]
 menu=''.join(f'<a class="{"active" if n==page else ""}" href="{u}">{ico(i)} {n}</a>' for u,n,i in nav)
 socials=[(SITE['github'],'GitHub','GH'),(SITE['x'],'X','𝕏'),(SITE['thm'],'TryHackMe','THM'),(SITE['htb'],'Hack The Box','HTB'),('mailto:'+SITE['email'],'Email','@')]
 links=''.join(f'<a href="{esc(u)}" target="_blank" rel="noopener noreferrer" title="{esc(n)}" aria-label="{esc(n)}"><span style="font-size:12px;font-weight:800">{mark}</span></a>' for u,n,mark in socials)
 return f'''<!doctype html><html lang="en" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{esc(desc)}"><title>{esc(title)} | verox</title><link rel="icon" href="assets/avatar.jpg"><link rel="stylesheet" href="assets/style.css"><script>try{{document.documentElement.dataset.theme=localStorage.getItem('theme')||'dark'}}catch(e){{}}</script></head><body><div id="overlay" class="overlay"></div><aside class="sidebar" id="sidebar"><a href="index.html"><img class="avatar" src="assets/avatar.jpg" alt="verox profile image"></a><a href="index.html" class="brand">verox</a><p class="tagline">Cybersecurity writeups, research<br>and thoughts.</p><nav class="nav" aria-label="Main navigation">{menu}</nav><div class="sidebottom"><div class="icons">{links}<button id="themeToggle" title="Toggle light and dark mode" aria-label="Toggle theme">{ico('moon')}</button></div><div class="sidecopy">© 2026 verox</div></div></aside><div class="shell"><main class="main"><header class="topbar"><div class="toptools"><button class="mobilemenu" id="mobileMenu" aria-label="Open menu">{ico('menu')}</button><span class="crumb">verox / {esc(page)}</span></div><div class="toptools"><a href="search.html" aria-label="Search">{ico('search')} &nbsp;Search</a></div></header>{body}<footer class="footer"><span>© 2026 verox · Built for the curious</span><span>Keep learning. Keep breaking things (ethically).</span></footer></main></div><script src="assets/app.js"></script></body></html>'''
def save(slug,title,body,desc=''): (ROOT/(slug+'.html')).write_text(layout(title if title in ['Home','Writeups','Thoughts','Categories','Tags','About','Search'] else 'Article',title,body,desc),encoding='utf-8')
hero=f'''<div class="pagehead"><h1>Hey, I'm verox <span style="color:var(--accent2)">↗</span></h1><p>Security enthusiast · CTF player · Always learning.</p></div><div class="featured"><span class="eyebrow">A little about this space</span><h2><a href="welcome-to-my-corner.html">Notes from the rabbit hole<span style="color:var(--accent)">_</span></a></h2><p>Welcome to my corner of the internet. A place for technical walkthroughs, things I've learned, and the occasional thought worth sharing.</p><div class="meta">{ico('terminal')} <span>Writeups · Research · Thoughts</span></div></div><div class="sectionbar"><h2>Recent posts</h2><a href="writeups.html">Explore writeups →</a></div>'''
save('index','Home',hero+''.join(postcard(p) for p in posts))
for kind,title,blurb in [('writeups','Writeups','Walkthroughs, practice notes, and security research.'),('thoughts','Thoughts','Ideas, lessons, reflections, and everything in between.')]:
 p=[x for x in posts if x['kind']==kind]
 save(kind,title,f'<div class="pagehead"><h1>{title}</h1><p>{blurb}</p></div>'+''.join(map(postcard,p)))
cats=['Hack The Box','TryHackMe','CTF','Research','Thoughts']
save('categories','Categories','<div class="pagehead"><h1>Categories</h1><p>Browse notes by topic.</p></div><div class="gridlinks">'+''.join(f'<a href="{("thoughts" if c=="Thoughts" else "writeups")}.html">{esc(c)} <small>{len([p for p in posts if p["category"]==c])} published / example posts</small></a>' for c in cats)+'</div>')
taglist=sorted(set(t for p in posts for t in p['tags']))
save('tags','Tags','<div class="pagehead"><h1>Tags</h1><p>Find content by keyword.</p></div><div class="pills" style="margin-bottom:28px">'+''.join(f'<a class="pill" href="#{esc(t.lower().replace(" ","-"))}">#{esc(t)}</a>' for t in taglist)+'</div>'+''.join(f'<section id="{esc(t.lower().replace(" ","-"))}"><h2>#{esc(t)}</h2>'+''.join(postcard(p) for p in posts if t in p['tags'])+'</section>' for t in taglist))
about=f'''<div class="pagehead"><h1>About me</h1><p>Just someone who likes figuring out how things work.</p></div><div class="about"><img src="assets/avatar.jpg" alt="Verox avatar"><div><h2 style="margin:0 0 6px">verox <span style="color:var(--accent2)">/ cybersecurity</span></h2><p style="color:var(--muted);margin:0">I am verox, a cybersecurity student focused on developing practical skills in offensive security, vulnerability assessment, and security research. I learn by exploring labs, tackling CTF challenges, and understanding how real-world systems can be attacked and defended. This blog is my space to document technical writeups, share lessons from hands-on practice, and reflect on ideas across cybersecurity. My goal is to keep improving, communicate what I learn clearly, and contribute useful knowledge to the security community.</p></div></div><h2>Find me online</h2><div class="sociallist"><div><strong>GitHub:</strong> <a href="{esc(SITE['github'])}">@abdullah-5j ↗</a></div><div><strong>TryHackMe:</strong> <a href="{esc(SITE['thm'])}">Verox. ↗</a></div><div><strong>Hack The Box:</strong> <a href="{esc(SITE['htb'])}">Profile ↗</a></div><div><strong>X / Twitter:</strong> <a href="{esc(SITE['x'])}">@abdullah5j009 ↗</a></div><div><strong>Discord:</strong> {esc(SITE['discord'])}</div><div><strong>Email:</strong> <a href="mailto:{esc(SITE['email'])}">{esc(SITE['email'])}</a></div></div><div class="notice">The writeups and thoughts on this site represent my learning journey. Sample posts are labeled as templates until replaced by original work.</div>'''
save('about','About',about)
save('search','Search','<div class="pagehead"><h1>Search</h1><p>Search titles, summaries, categories, and tags.</p></div><label class="searchbox">'+ico('search')+'<input id="searchInput" type="search" placeholder="Type to search posts…" autofocus aria-label="Search posts"></label><div id="searchResults">'+''.join(postcard(p) for p in posts)+'</div><p class="empty" id="noResults" hidden>No matching posts found.</p>')
markdown=mistune.create_markdown(plugins=['table','strikethrough','task_lists','url'])
for p in posts:
 raw=(ROOT/'posts'/p['file']).read_text()
 body=f'<article class="article"><h1>{esc(p["title"])}</h1>{meta(p)}'+ ('<div class="notice"><strong>Example content:</strong> This is a starter template, not a claim that this machine/room was completed. Replace it with your own notes before publishing.</div>' if p.get('sample') else '')+f'<div class="prose">{markdown(raw)}</div>{pills(p)}<p style="margin-top:40px"><a href="{p["kind"]}.html">← Back to {p["kind"]}</a></p></article>'
 save(p['slug'],p['title'],body,p['summary'])
(ROOT/'site.json').write_text(json.dumps({'profile':SITE,'posts':posts},indent=2))
print('Build complete:',len(list(ROOT.glob('*.html'))),'HTML pages')
